-- :Reference (Space ?) — the ntex reference page, reference/index.html.
--
-- The page is generated by reference/build.mjs from the live sources
-- (the loaded snippets, prefs.lua, the real keymaps). It is rebuilt
--   * in the background when a snippet file is saved and reloaded (hooked
--     from lua/snips/init.lua); silent unless the build fails;
--   * by :Reference when any source is newer than the page (:Reference! always).
-- Inside cmux it opens in a browser split to the right and the cursor stays
-- here; the same pane is reused (and reloaded after a rebuild). Elsewhere: `open`.
local M = {}
local uv = vim.uv

local cfg = vim.fn.stdpath("config")
local dir = vim.fs.joinpath(cfg, "reference")
M.index = vim.fs.joinpath(dir, "index.html")

local function find_node()
  local candidates = { vim.fn.exepath("node"), "/opt/homebrew/bin/node", "/usr/local/bin/node" }
  local nvm = vim.fn.glob(vim.env.HOME .. "/.nvm/versions/node/*/bin/node", false, true)
  table.sort(nvm)
  for k = #nvm, 1, -1 do
    candidates[#candidates + 1] = nvm[k]
  end
  for _, c in ipairs(candidates) do
    if c ~= "" and vim.fn.executable(c) == 1 then
      return c
    end
  end
end

local function mtime(p)
  local st = uv.fs_stat(p)
  return st and (st.mtime.sec + st.mtime.nsec / 1e9) or 0
end

--- every file the page is built from
function M.inputs()
  local files = {}
  local function add(list)
    for _, f in ipairs(list) do
      files[#files + 1] = f
    end
  end
  add(vim.fn.globpath(vim.fs.joinpath(cfg, "snippets"), "tex/*.lua", false, true))
  add({ vim.fs.joinpath(cfg, "snippets", "decisions.json") })
  add({ vim.fs.joinpath(cfg, "prefs.lua"), vim.fs.joinpath(cfg, "init.lua"), vim.fs.joinpath(cfg, "lazy-lock.json"), vim.fs.joinpath(cfg, "templates", "article.tex") })
  add(vim.fn.globpath(cfg, "lua/**/*.lua", false, true))
  add(vim.fn.globpath(dir, "*.mjs", false, true))
  add(vim.fn.globpath(dir, "verify.lua", false, true))
  add(vim.fn.globpath(dir, "lib/*.mjs", false, true))
  add(vim.fn.globpath(dir, "content/*.mjs", false, true))
  add(vim.fn.globpath(dir, "client/*", false, true))
  return files
end

function M.stale()
  local built = mtime(M.index)
  if built == 0 then
    return true
  end
  for _, f in ipairs(M.inputs()) do
    if mtime(f) > built then
      return true
    end
  end
  return false
end

-- build --------------------------------------------------------------------

local running, again, waiters = false, false, {}

--- Build in the background. cb(ok) runs on the main loop when done.
function M.build(cb)
  if cb then
    waiters[#waiters + 1] = cb
  end
  if running then
    again = true
    return
  end
  local node = find_node()
  if not node then
    vim.notify("ntex reference: node not found, can't build the page", vim.log.levels.ERROR)
    return
  end
  running = true
  vim.system({ node, vim.fs.joinpath(dir, "build.mjs"), "--quiet" }, { text = true }, function(res)
    vim.schedule(function()
      running = false
      local ok = res.code == 0
      if not ok then
        local msg = vim.trim((res.stderr or "") .. "\n" .. (res.stdout or ""))
        vim.notify("ntex reference: build failed (node " .. vim.fs.joinpath("~/.config/texnvim/reference", "build.mjs") .. " shows why)\n" .. msg:sub(1, 800), vim.log.levels.ERROR)
      end
      if again then
        again = false
        return M.build()
      end
      local list = waiters
      waiters = {}
      for _, f in ipairs(list) do
        pcall(f, ok)
      end
      if ok then
        M.reload_pane()
      end
    end)
  end)
end

--- Called by lua/snips/init.lua after a snippet file was saved and reloaded.
function M.on_sources_changed()
  -- tests and the build's own headless ntex point TEXNVIM_SNIPPETS elsewhere
  if vim.env.TEXNVIM_NO_REFERENCE == "1" or vim.env.TEXNVIM_SNIPPETS then
    return
  end
  M.build()
end

-- open ---------------------------------------------------------------------

local pane -- "surface:N" of the cmux browser split showing the page

local function in_cmux()
  return (vim.env.CMUX_WORKSPACE_ID or vim.env.CMUX_SOCKET_PATH or vim.env.CMUX_SURFACE_ID) ~= nil
end

local function cmux(args)
  local res = vim.system(vim.list_extend({ "cmux" }, args), { text = true }):wait(5000)
  return res.code == 0, (res.stdout or "") .. (res.stderr or "")
end

local function pane_alive()
  return pane ~= nil and (cmux({ "identify", "--surface", pane, "--no-caller" }))
end

local function url()
  return "file://" .. M.index
end

function M.reload_pane()
  if pane and in_cmux() then
    vim.system({ "cmux", "browser", pane, "navigate", url() })
  end
end

function M.open()
  if vim.env.TEXNVIM_NO_VIEWER == "1" then
    vim.notify("ntex reference: not opening (TEXNVIM_NO_VIEWER=1)", vim.log.levels.INFO)
    return
  end
  if vim.fn.filereadable(M.index) == 0 then
    vim.notify("ntex reference: the page hasn't been built yet", vim.log.levels.WARN)
    return
  end
  if in_cmux() then
    if pane_alive() then
      cmux({ "browser", pane, "navigate", url() })
      return
    end
    local ok, out = cmux({ "browser", "open-split", url(), "--focus", "false" })
    if ok then
      pane = out:match("(surface:%d+)")
      return
    end
    vim.notify("ntex reference: cmux couldn't open a browser split (" .. vim.trim(out) .. "), using the default browser", vim.log.levels.WARN)
  end
  vim.system({ "open", url() })
end

function M.setup()
  vim.api.nvim_create_user_command("Reference", function(o)
    if o.bang or M.stale() then
      vim.notify("ntex reference: rebuilding the page…", vim.log.levels.INFO)
      M.build(function(ok)
        if ok or vim.fn.filereadable(M.index) == 1 then
          M.open()
        end
      end)
    else
      M.open()
    end
  end, { bang = true, desc = "Open the ntex reference page (rebuilds it first if a source changed; ! = always)" })
end

return M
